    "starter": "import matplotlib.pyplot as plt\n\nmonths = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\"]\nriyadh = [24, 29, 37, 19, 29, 22]\njeddah = [18, 21, 25, 27, 30, 34]",
    "solution": "import matplotlib.pyplot as plt\n\nmonths = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\"]\nriyadh = [24, 29, 37, 19, 29, 22]\njeddah = [18, 21, 25, 27, 30, 34]\n\nfig, ax = plt.subplots()\nax.plot(months, riyadh, color=\"#2c7be5\", marker=\"o\", label=\"Riyadh\")\nax.plot(months, jeddah, color=\"#e5732c\", linestyle=\"--\", label=\"Jeddah\")\nax.set_title(\"Jeddah is catching up\")\nax.legend()\nax.spines[[\"top\", \"right\"]].set_visible(False)\nplt.show()",
